  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    gap: Spacing.two,
  },
  name: {
    fontFamily: RubikFonts.medium,
    fontSize: 24,
    lineHeight: 30,
  },
});

