  },
  nameStrip: {
    paddingHorizontal: Spacing.twoAndHalf,
    paddingVertical: Spacing.twoAndHalf,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: Spacing.one,
  },
  name: {
    flex: 1,
    fontSize: 16,
    lineHeight: 20,
  },
  moreButton: {
    width: Spacing.four,
    height: Spacing.four,
    alignItems: 'center',
    justifyContent: 'center',
  },
  moreText: {
    fontSize: 24,
